#[cfg(feature = "validate")]
#[test]
fn rejects_invalid_examples() {
    use trust_tasks_rs::validate::ValidatedPayload;
    let fixtures: &[(&str, &str)] = &[
        (
            "Revision 1 MUST NOT carry `editedAt`: a first revision was never edited.",
            "{\n  \"body\": \"See you at three.\",\n  \"editedAt\": \"2026-11-08T09:15:40Z\",\n  \"kind\": \"message\",\n  \"messageId\": \"q3Xv9LbT2mWc7RkN4sYh1PdZ8uFa6JeG0oVi5xQnB2E\",\n  \"revision\": 1,\n  \"writtenAt\": \"2026-11-08T09:14:02Z\"\n}",
        ),
        (
            "Revision 1 MUST NOT have an empty `body`: only a rewrite can withdraw.",
            "{\n  \"body\": \"\",\n  \"kind\": \"message\",\n  \"messageId\": \"q3Xv9LbT2mWc7RkN4sYh1PdZ8uFa6JeG0oVi5xQnB2E\",\n  \"revision\": 1,\n  \"writtenAt\": \"2026-11-08T09:14:02Z\"\n}",
        ),
        (
            "Every revision after the first MUST carry `editedAt`.",
            "{\n  \"body\": \"See you at four.\",\n  \"kind\": \"message\",\n  \"messageId\": \"q3Xv9LbT2mWc7RkN4sYh1PdZ8uFa6JeG0oVi5xQnB2E\",\n  \"revision\": 2,\n  \"writtenAt\": \"2026-11-08T09:14:02Z\"\n}",
        ),
        (
            "A reaction MUST name its target in `inReplyTo`.",
            "{\n  \"body\": \"👍\",\n  \"kind\": \"reaction\",\n  \"messageId\": \"Hk2pW8nQ4cZt6YvR1mLs9BxE3fJa7GuD5oTi0wKeN8M\",\n  \"revision\": 1,\n  \"writtenAt\": \"2026-11-08T09:16:10Z\"\n}",
        ),
        (
            "`messageId` is exactly 43 base64url characters (32 random bytes).",
            "{\n  \"body\": \"See you at three.\",\n  \"kind\": \"message\",\n  \"messageId\": \"msg-1\",\n  \"revision\": 1,\n  \"writtenAt\": \"2026-11-08T09:14:02Z\"\n}",
        ),
        (
            "Unknown member: a direct message carries no rooms library members such as `title`.",
            "{\n  \"body\": \"See you at three.\",\n  \"kind\": \"message\",\n  \"messageId\": \"q3Xv9LbT2mWc7RkN4sYh1PdZ8uFa6JeG0oVi5xQnB2E\",\n  \"revision\": 1,\n  \"title\": \"Meeting\",\n  \"writtenAt\": \"2026-11-08T09:14:02Z\"\n}",
        ),
        (
            "`inReplyTo` names a message by `messageId` alone; there is no host `version` to name.",
            "{\n  \"body\": \"Yes, three works.\",\n  \"inReplyTo\": {\n    \"messageId\": \"q3Xv9LbT2mWc7RkN4sYh1PdZ8uFa6JeG0oVi5xQnB2E\",\n    \"version\": 1\n  },\n  \"kind\": \"message\",\n  \"messageId\": \"Zr5tN1vB8kQw3HxM6cLp2YdS9gFa4JeU7oRi0nWqT1A\",\n  \"revision\": 1,\n  \"writtenAt\": \"2026-11-08T09:15:00Z\"\n}",
        ),
        (
            "`writtenAt` is UTC with a `Z` designator, never an offset.",
            "{\n  \"body\": \"See you at three.\",\n  \"kind\": \"message\",\n  \"messageId\": \"q3Xv9LbT2mWc7RkN4sYh1PdZ8uFa6JeG0oVi5xQnB2E\",\n  \"revision\": 1,\n  \"writtenAt\": \"2026-11-08T10:14:02+01:00\"\n}",
        ),
        (
            "`revision` starts at 1.",
            "{\n  \"body\": \"See you at three.\",\n  \"kind\": \"message\",\n  \"messageId\": \"q3Xv9LbT2mWc7RkN4sYh1PdZ8uFa6JeG0oVi5xQnB2E\",\n  \"revision\": 0,\n  \"writtenAt\": \"2026-11-08T09:14:02Z\"\n}",
        ),
        (
            "Bare/unnamespaced ext key — SPEC §4.5.1 requires every immediate child of ext to be reverse-DNS namespaced.",
            "{\n  \"body\": \"See you at three.\",\n  \"ext\": {\n    \"bare\": true\n  },\n  \"kind\": \"message\",\n  \"messageId\": \"q3Xv9LbT2mWc7RkN4sYh1PdZ8uFa6JeG0oVi5xQnB2E\",\n  \"revision\": 1,\n  \"writtenAt\": \"2026-11-08T09:14:02Z\"\n}",
        ),
    ];
    for (i, (note, raw)) in fixtures.iter().enumerate() {
        let value: serde_json::Value = match serde_json::from_str(raw) {
            Ok(v) => v,
            Err(_) => continue,
        };
        let serde_ok = serde_json::from_value::<spec::Payload>(value.clone()).is_ok();
        let schema_ok = spec::Payload::validate_value(&value).is_ok();
        assert!(
            !(serde_ok && schema_ok),
            "invalid-example #{} ({:?}) was accepted by both serde and JSON Schema; \
                         the fixture's stated failure class is no longer caught:\n{}",
            i + 1,
            note,
            raw
        );
    }
}
